	var data;
	var out;
	var A;

	data = ROW_MAJOR_DATA;
	A = data.A.slice();
	expected = data.A.slice();
	out = gswapRows( data.order, data.M, 0, data.i, data.j, A, data.LDA );

	t.strictEqual( out, A, 'returns expected value' );
